'use strict';

/**
 * src/core/utils/idValidation.js
 *
 * WHAT THIS FILE DOES:
 *   Provides standardized Joi validation schemas and helpers for CUID and identifier strings.
 *   Ensures cross-module consistency for primary keys and foreign keys (product_id, category_id,
 *   user_id, admin_user_id, document_id, etc.).
 *
 * OVERALL DESIGN:
 *   Validates string identifiers with length and format guards while remaining flexible
 *   for CUID strings generated by Prisma (cuid/cuid2) and mock identifiers in automated tests.
 *
 * ELEMENTS IN THIS FILE:
 *   - cuidSchema: Base Joi validator for string IDs (trimmed string between 10 and 36 characters)
 *   - cuidRequired: Mandatory CUID string validator
 *   - cuidOptional: Optional/nullable CUID string validator
 *   - validateCuid(id, fieldName): Helper function to validate a single ID parameter
 *
 * FINAL OUTPUT OF THE FILE:
 *   Exported object containing Joi validation schemas and helper functions for ID validation.
 */

const Joi = require('joi');
const ApiError = require('./ApiError');

// CUID string schema supporting standard CUIDs and test mock strings
const cuidSchema = Joi.string().trim().min(10).max(36);
const cuidRequired = cuidSchema.required();
const cuidOptional = cuidSchema.optional().allow(null, '');

/**
 * validateCuid
 *
 * USE:
 *   Explicitly validates a single identifier string, throwing a formatted 400 ApiError if invalid.
 *
 * HOW IT WORKS:
 *   1. Evaluates the given ID against cuidRequired schema.
 *   2. If validation fails, constructs a 400 Bad Request ApiError with specific error details.
 *   3. Returns the sanitized and trimmed string.
 *
 * CONCEPTS:
 *   Joi validation, fail-fast input sanitation, HTTP 400 envelope.
 *
 * PLACES IMPORTED AND USED:
 *   Used in controllers and route middleware across documents, testimonials, faqs, dealers, and feedback.
 *
 * FINAL OUTPUT:
 *   Sanitized string ID or throws ApiError.
 *
 * @param {string} id - The ID string to validate
 * @param {string} [fieldName='id'] - The parameter name for the error message
 * @returns {string} The validated, trimmed ID string
 */
function validateCuid(id, fieldName = 'id') {
  const { error, value } = cuidRequired.validate(id);
  if (error) {
    throw ApiError.badRequest(`Invalid ${fieldName}: must be a valid identifier string`);
  }
  return value;
}

module.exports = {
  cuidSchema,
  cuidRequired,
  cuidOptional,
  validateCuid,
};
